/**
 * A2A skill emission: one authored `A2ASkill` entry → its
 * `elementum_agent_a2a_skill` resource block. Unlike agent tools, an A2A
 * skill carries no `app_id` and no target/field references — it's pure
 * metadata (name/description/tags/examples/input+output modes) describing
 * what the agent offers to OTHER agents (provider/docs/resources/
 * agent_a2a_skill.md). Owner passed in — this module never names the
 * owning app.
 */
import { type TfBlock } from "../../engine/tf/index.js";
export interface A2ASkillWire {
    readonly name?: string;
    readonly description?: string;
    readonly tags?: readonly string[];
    readonly examples?: readonly string[];
    readonly inputModes?: readonly string[];
    readonly outputModes?: readonly string[];
}
export interface A2ASkillToTfContext {
    /** The owning app's tfLabel (namespace) — scopes the child label. */
    readonly appTfLabel: string;
    /** The owning agent's bare tfLabel (before the apps_ prefix). */
    readonly agentBareTfLabel: string;
    /**
     * Cross-agent disambiguation suffix ("", "_1", "_2", …) — mirrors ei's
     * own a2a-skill collision handling across different agents in the same
     * app (board issue #294). Computed by the caller (`agentToTf`) via
     * `computeA2ASkillLabelSuffixes`; empty when absent (single-agent
     * contexts, most unit tests).
     */
    readonly labelSuffix?: string;
    /** Degradations land here — reported by the caller, never silent. */
    readonly diagnostics: string[];
}
export interface A2ASkillToTfResult {
    readonly block: TfBlock;
    readonly address: string;
}
/** One authored `A2ASkill` entry → its resource block; undefined = degraded (diagnostic already pushed). */
export declare function a2aSkillToTf(entry: A2ASkillWire, ctx: A2ASkillToTfContext): A2ASkillToTfResult | undefined;
